reproduction_inner_command:
if [ ! -x /gt/_out/fuzz-mdhtml ]; then cd /gt/_work/src && (set -euo pipefail
cd /gt/_work/src
cat > /tmp/afl_driver.c <<"EOF"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "usage: %s <input>\n", argv[0]);
    return 2;
  }
  FILE *f = fopen(argv[1], "rb");
  if (!f) {
    perror("fopen");
    return 2;
  }
  if (fseek(f, 0, SEEK_END) != 0) {
    perror("fseek");
    fclose(f);
    return 2;
  }
  long len = ftell(f);
  if (len < 0) {
    perror("ftell");
    fclose(f);
    return 2;
  }
  rewind(f);
  uint8_t *buf = NULL;
  if (len > 0) {
    buf = (uint8_t *)malloc((size_t)len);
    if (!buf) {
      fprintf(stderr, "malloc failed\n");
      fclose(f);
      return 2;
    }
    if (fread(buf, 1, (size_t)len, f) != (size_t)len) {
      perror("fread");
      free(buf);
      fclose(f);
      return 2;
    }
  }
  fclose(f);
  int rc = LLVMFuzzerTestOneInput(buf, (size_t)len);
  free(buf);
  return rc;
}
EOF
export CC=clang CXX=clang++
export CFLAGS="-O1 -fno-omit-frame-pointer -gline-tables-only -DFUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION -fsanitize=address"
export CXXFLAGS="$CFLAGS"
rm -rf /gt/_out /gt/_work/src/build && mkdir -p /gt/_out
mkdir build && cd build
cmake ../ -DBUILD_SHARED_LIBS=OFF
make -j"$(nproc)"
$CC $CFLAGS -c ../test/fuzzers/fuzz-mdhtml.c -I../src -o fuzz-mdhtml.o
$CC $CFLAGS -c /tmp/afl_driver.c -o afl_driver.o
$CXX $CXXFLAGS fuzz-mdhtml.o afl_driver.o -o /gt/_out/fuzz-mdhtml ./src/libmd4c-html.a ./src/libmd4c.a) || exit $?; fi; cd /gt/_work/src && ASAN_OPTIONS=detect_leaks=0:abort_on_error=1:symbolize=1 /gt/_out/fuzz-mdhtml /gt/poc

